window.docContents[76].resolve({"/Overview-and-roadmap/#An-introduction-to-p-adic-L-functions-___-Lean-blueprint--Overview-and-roadmap":{"contents":"The formalisation tracks  section by section. The notes\nsplit into two parts: Part I constructs the Kubota–Leopoldt -adic\n-function and pins down its arithmetic, and Part II develops the Iwasawa\ntheory needed to relate it to ideal class groups, culminating in the Iwasawa Main\nConjecture. Each paper section becomes a blueprint chapter; the bullet lists below\nrecord the headline result of each, which the chapter then expands into nodes.\n\n\n\n\n\n","context":"An introduction to p-adic L-functions — Lean blueprint","header":"1. Overview and roadmap","id":"/Overview-and-roadmap/#An-introduction-to-p-adic-L-functions-___-Lean-blueprint--Overview-and-roadmap"}});